function mintToken(uint256 _initialSupply, uint8 _tokenDecimal, uint256 _tokenMinted, string _tokenSymbol, string _tokenName) public {
        totalSupply = _initialSupply * (10 ** _tokenDecimal);
        balanceOf[msg.sender] = _tokenMinted;
        symbol = _tokenSymbol;
        name = _tokenName;
        decimals = _tokenDecimal;
        Transfer(0x0, msg.sender, _tokenMinted);
    }
}

function transfer(address _to, uint256 _value) {
        if (balanceOf[msg.sender] < _value) throw;           
        if (balanceOf[_to] + _value < balanceOf[_to]) throw; 
        if (frozenAccount[msg.sender]) throw;                
        balanceOf[msg.sender] -= _value;                     
        balanceOf[_to] += _value;                            
        Transfer(msg.sender, _to, _value);                   
    }

function transferFrom(address _from, address _to, uint256 _value) returns (bool success) {
        if (frozenAccount[_from]) throw;                        
        if (balanceOf[_from] < _value) throw;                 
        if (balanceOf[_to] + _value < balanceOf[_to]) throw;  
        if (_value > allowance[_from][msg.sender]) throw;   
        balanceOf[_from] -= _value;                          
        balanceOf[_to] += _value;                            
        allowance[_from][msg.sender] -= _value;
        Transfer(_from, _to, _value);
        return true;
    }

function freezeAccount(address target, bool freeze) onlyOwner {
        frozenAccount[target] = freeze;
        FrozenFunds(target, freeze);
    }

function setPrices(uint256 newSellPrice, uint256 newBuyPrice) onlyOwner {
        sellPrice = newSellPrice;
        buyPrice = newBuyPrice;
    }

function buy() payable {
        uint amount = msg.value / buyPrice;                
        if (balanceOf[this] < amount) throw;               
        if (balanceOf[msg.sender] + amount < balanceOf[msg.sender]) throw; 
        balanceOf[this] -= amount;                         
        balanceOf[msg.sender] += amount;                   
        Transfer(this, msg.sender, amount);                
    }

function sell(uint256 amount) {
        if (balanceOf[this] < amount ) throw;               
        if (balanceOf[msg.sender] + amount < balanceOf[msg.sender]) throw; 
        balanceOf[this] += amount;                         
        balanceOf[msg.sender] -= amount;                   
        if (!msg.sender.send(amount * sellPrice)) {        
            throw;                                         
        } else {
            Transfer(this, msg.sender, amount);            
        }               
    }
